{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '평범한 사람이라는 게 드러날까 봐요'라고 말한 것은 핵심 신념 문장('내가 진짜로 도전하면 결국 평범하고 무능한 사람이라는 것이 드러날 것이다')과 직접적으로 일치함. 성장 경험에서 아버지의 '밥벌이는 따로 찾아라', 친척의 '사진은 누구나 찍지 않느냐'라는 반응이 이 신념의 기원을 설명함."
    },
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/situations/2"],
      "relevance": "내담자가 '이 정도밖에 안 되는 사람이구나'라는 자기 평가를 한 것은 실패 스키마(도전 결과를 자신의 전반적 능력에 대한 판정으로 해석)가 작동하는 모습. 상담에서 직접 언급한 지원금 마감 상황(30장 폴더 넣기만 하면 됐는데 못 낸 경험)이 이 스키마의 실증적 사례임."
    },
    {
      "trait_id": "/core_belief/schema_definition",
      "background_ids": ["/situations/0", "/situations/1"],
      "relevance": "상담사가 '평범한 사람이라는 게 드러나면 어떤 일이 생길 것 같냐'고 물은 것은, 내담자가 도전을 자신의 가치에 대한 판정으로 해석하는 패턴을 더 깊이 탐색하려는 질문. 큐레이터 제안 시 '보내면 별것 없다는 걸 바로 알아차릴 텐데', 친구가 사진 보자고 할 때 '다 비슷하고 아무 말도 없다는 걸 알 거야'라는 자동사고가 이 정의를 구체적으로 보여줌."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/situations/3"],
      "relevance": "내담자가 '평범한 사람이 드러나는 것'을 두려워하는 것은 '작품을 끝까지 내놓고도 인정받지 못하는 것은 재능이 없다는 최종 판결과 같다'는 태도와 연결. 누나가 가족 앞에서 전시를 언급했을 때 '결국 못 할 거라고 생각하면서도 겉으로만 응원하는 거야'라고 해석한 것은 이 태도가 가족 관계 맥락에서 작동하는 사례."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/childhood_data"],
      "relevance": "'평범한 사람이 드러나면 어떤 일이 생길 것 같냐'는 질문에 대해, 내담자의 부정적 가정(온 힘을 다해 내놓았는데 반응이 없으면 변명 없이 실패가 증명됨)이 답이 될 가능성. 성장 경험에서 '좋아하는 일을 진지하게 시도할수록 평범함이 들킬 것'이라는 인식이 이 가정의 원형임."
    }
  ]
}

